const SHIFTS = {
  MORNING: { name: 'Morning', startTime: '06:00' },
  EVENING: { name: 'Evening', startTime: '14:00' },
  NIGHT: { name: 'Night', startTime: '22:00' },
  FREE: { name: 'Free', startTime: '-' }
};

function getWeekNumber(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  // Thursday in current week decides the year
  d.setDate(d.getDate() + 3 - (d.getDay() + 6) % 7);
  // January 4 is always in week 1
  const week1 = new Date(d.getFullYear(), 0, 4);
  // Adjust to Thursday in week 1 and count number of weeks from date to week1
  return 1 + Math.round(((d.getTime() - week1.getTime()) / 86400000 - 3 + (week1.getDay() + 6) % 7) / 7);
}

function getShiftRotation(date) {
  const year = date.getFullYear();
  const weekNumber = getWeekNumber(date);
  
  // Only process for 2025 and beyond
  if (year < 2025) return null;
  
  // Calculate weeks since start of 2025
  const weeksFrom2025 = ((year - 2025) * 52) + weekNumber;
  const rotationCycle = (weeksFrom2025 - 1) % 3;

  // Check if it's Saturday
  const dayOfWeek = date.getDay();
  if (dayOfWeek === 6) {
    return {
      A: SHIFTS.FREE,
      B: SHIFTS.FREE,
      C: SHIFTS.FREE
    };
  }

  // For Sunday, check next week's pattern to determine if it's a night shift
  if (dayOfWeek === 0) {
    // Get next week's rotation pattern
    const nextWeekRotation = (rotationCycle + 1) % 3;
    
    // If next week starts with night shift for any team, that team works Sunday night
    const sundayPattern = {
      0: { A: SHIFTS.FREE, B: SHIFTS.NIGHT, C: SHIFTS.FREE },    // Next week: B night
      1: { A: SHIFTS.NIGHT, B: SHIFTS.FREE, C: SHIFTS.FREE },    // Next week: A night
      2: { A: SHIFTS.FREE, B: SHIFTS.FREE, C: SHIFTS.NIGHT }     // Next week: C night
    };
    
    return sundayPattern[rotationCycle];
  }

  // Define shift patterns based on rotation cycle for weekdays
  const shiftPatterns = {
    0: { A: SHIFTS.MORNING, B: SHIFTS.NIGHT, C: SHIFTS.EVENING },
    1: { A: SHIFTS.NIGHT, B: SHIFTS.EVENING, C: SHIFTS.MORNING },
    2: { A: SHIFTS.EVENING, B: SHIFTS.MORNING, C: SHIFTS.NIGHT }
  };

  return shiftPatterns[rotationCycle];
}

function getCurrentShift(team) {
  const now = new Date();
  const currentRotation = getShiftRotation(now);
  
  if (!currentRotation || !team) return null;
  
  return currentRotation[team];
}

export { SHIFTS, getShiftRotation, getCurrentShift }; 